<template>
  <section class="git-repository-panel" :class="{ 'dark-mode': isDark }">
    <div v-if="error" class="git-alert" role="alert"><i class="fa fa-exclamation-triangle"></i><span>{{ error }}</span><button type="button" @click="loadAll">重新加载</button></div>
    <div v-if="loading" class="git-repository-panel__skeleton"><span v-for="index in 6" :key="index" :style="{ width: `${42 + index * 8}%` }"></span></div>

    <template v-else-if="repository">
      <header class="git-repository-panel__hero">
        <div class="git-repository-panel__identity"><span class="git-repository-panel__icon"><i class="fa fa-code-fork"></i></span><div><div class="git-repository-panel__heading"><h1>{{ repository.name }}</h1><span>{{ repository.defaultBranch }}</span><span>{{ repository.hashAlgorithm.toUpperCase() }}</span></div><p>{{ repository.description || 'Git 代码仓库：通过分支、提交图与 CloudFlow 自动化管理版本化资源。' }}</p><small>更新于 {{ formatDate(repository.updatedAt) }} · {{ formatFileSize(repository.objectBytes) }} 对象数据</small></div></div>
        <div class="git-repository-panel__hero-actions"><button type="button" class="git-social-button" :class="{ active: repository.starred }" :disabled="socialBusy" @click="toggleStar"><i :class="repository.starred ? 'fa fa-star' : 'fa fa-star-o'"></i>{{ repository.starCount || 0 }} Star</button><button type="button" @click="openForkDialog"><i class="fa fa-code-fork"></i>{{ repository.forkCount || 0 }} Fork</button><button type="button" @click="cloneDialogOpen = true"><i class="fa fa-clone"></i>克隆</button><button type="button" @click="downloadArchive"><i class="fa fa-file-archive-o"></i>下载 ZIP</button><button v-if="isOwner" type="button" @click="manageDialogOpen = true"><i class="fa fa-cog"></i><span class="hidden sm:inline">管理</span></button></div>
      </header>

      <section class="git-repository-panel__stats" aria-label="仓库真实统计">
        <div><i class="fa fa-history"></i><b>{{ insights.commitCount.toLocaleString('zh-CN') }}</b><span>提交</span></div><div><i class="fa fa-code-fork"></i><b>{{ insights.branchCount }}</b><span>分支</span></div><div><i class="fa fa-tag"></i><b>{{ insights.tagCount }}</b><span>标签</span></div><div><i class="fa fa-users"></i><b>{{ insights.contributorCount }}</b><span>贡献者</span></div><div><i class="fa fa-star"></i><b>{{ repository.starCount || 0 }}</b><span>Star</span></div><div><i class="fa fa-code-fork"></i><b>{{ repository.forkCount || 0 }}</b><span>Fork</span></div><div><i class="fa fa-cubes"></i><b>{{ repository.objectCount.toLocaleString('zh-CN') }}</b><span>Git Objects</span></div>
      </section>

      <nav class="git-repository-panel__tabs" aria-label="仓库功能标签">
        <button v-for="tab in tabs" :key="tab.id" type="button" :class="{ active: activeTab === tab.id }" :aria-current="activeTab === tab.id ? 'page' : undefined" @click="setTab(tab.id)"><i :class="tab.icon"></i>{{ tab.label }}<b v-if="tab.count !== undefined">{{ tab.count }}</b></button>
      </nav>

      <section v-if="activeTab === 'code'" class="git-repository-panel__tab"><GitCodeWorkspace :repository-id="repository.repoId" :repository-name="repository.name" :ref-name="selectedRef" :refs="allRefs" :is-dark="isDark" :initial-path="routePath" :initial-line="routeLine" @change-ref="changeRef" @clone="cloneDialogOpen = true" @open-history="openFileHistory" @file-change="syncFilePath" @toast="showToast" /></section>
      <section v-else-if="activeTab === 'readme'" class="git-repository-panel__tab git-repository-panel__tab--card"><div v-if="readmeLoading" class="git-repository-panel__content-skeleton"><span v-for="index in 12" :key="index"></span></div><div v-else-if="!readmeContent" class="git-empty"><i class="fa fa-book"></i><h2>该引用尚未提供 README</h2><p>在仓库根目录添加 README.md 后，此处会按 GitHub 风格渲染。</p></div><MarkdownPreview v-else :markdown-content="readmeContent" :file-name="readmeName" :dark-mode="isDark" /></section>
      <section v-else-if="activeTab === 'commits'" class="git-repository-panel__tab"><GitCommitGraph :repository-id="repository.repoId" :ref-name="selectedRef" :refs="allRefs" :file-path="historyPath" @clear-file-history="historyPath = ''" @toast="showToast" /></section>
      <section v-else-if="activeTab === 'merge-requests'" class="git-repository-panel__tab git-repository-panel__tab--card">
        <header class="git-repository-panel__section-head"><div><h2>合并请求</h2><p>基于源分支与目标分支审查代码变更。</p></div><div><select v-model="mrStatus" @change="loadMergeRequests"><option value="">全部</option><option value="OPEN">已打开</option><option value="MERGED">已合并</option><option value="CLOSED">已关闭</option></select><button v-if="isOwner" type="button" class="git-primary-button" @click="showMergeForm = !showMergeForm"><i class="fa fa-plus"></i>新建合并请求</button></div></header>
        <form v-if="showMergeForm && isOwner" class="git-repository-panel__form" @submit.prevent="createMergeRequest"><input v-model.trim="mergeForm.title" required maxlength="200" placeholder="合并请求标题" /><select v-model="mergeForm.sourceBranch" required><option value="" disabled>源分支</option><option v-for="branch in branches" :key="branch.name" :value="branch.name">{{ branch.name }}</option></select><select v-model="mergeForm.targetBranch" required><option value="" disabled>目标分支</option><option v-for="branch in branches" :key="branch.name" :value="branch.name">{{ branch.name }}</option></select><textarea v-model.trim="mergeForm.description" maxlength="4000" placeholder="描述（可选）"></textarea><button class="git-primary-button" :disabled="mergeSubmitting">{{ mergeSubmitting ? '提交中…' : '提交合并请求' }}</button></form>
        <div v-if="mergeLoading" class="git-repository-panel__content-skeleton"><span v-for="index in 5" :key="index"></span></div><div v-else-if="!mergeRequests.length" class="git-empty"><i class="fa fa-code-fork"></i><h2>暂无合并请求</h2><p>推送新的主题分支后可在这里发起代码审查。</p></div><div v-else class="git-repository-panel__mr-list"><article v-for="item in mergeRequests" :key="item.mergeRequestId" :class="{ active: selectedMergeRequest?.mergeRequestId === item.mergeRequestId }" @click="selectMergeRequest(item)"><div><span class="git-status" :class="item.status.toLowerCase()">{{ item.status }}</span><h3>#{{ item.number }} {{ item.title }}</h3><p>{{ item.sourceBranch }} <i class="fa fa-long-arrow-right"></i> {{ item.targetBranch }} · {{ item.approvalStatus }}</p></div><time>{{ formatRelative(item.updatedAt) }}</time></article></div>
        <section v-if="selectedMergeRequest" class="git-repository-panel__mr-detail"><header><div><span>MR #{{ selectedMergeRequest.number }}</span><h3>{{ selectedMergeRequest.title }}</h3><p>{{ selectedMergeRequest.description || '暂无描述' }}</p></div><button type="button" @click="selectedMergeRequest = null"><i class="fa fa-times"></i></button></header><p class="git-repository-panel__mr-meta">{{ selectedMergeRequest.sourceBranch }} → {{ selectedMergeRequest.targetBranch }} · 审批状态：{{ selectedMergeRequest.approvalStatus }}</p><div class="git-repository-panel__mr-actions"><button type="button" class="git-secondary-button" :disabled="mrDiffLoading" @click="loadMergeDiff">{{ mrDiffLoading ? '正在生成差异…' : '查看代码差异' }}</button><button v-if="selectedMergeRequest.status === 'OPEN'" type="button" class="git-secondary-button" @click="reviewMergeRequest('APPROVED')"><i class="fa fa-check"></i>批准</button><button v-if="selectedMergeRequest.status === 'OPEN'" type="button" class="git-secondary-button" @click="reviewMergeRequest('CHANGES_REQUESTED')"><i class="fa fa-pencil"></i>请求修改</button><button v-if="isOwner && selectedMergeRequest.status === 'OPEN'" type="button" class="git-primary-button" @click="mergeMergeRequest"><i class="fa fa-code-fork"></i>合并</button></div><GitDiffViewer v-if="mrDiff" :diff="mrDiff" file-name="合并请求差异" @toast="showToast" /><section class="git-repository-panel__comments"><h4>讨论</h4><p v-if="commentsLoading" class="git-repository-panel__comments-empty"><i class="fa fa-circle-o-notch fa-spin"></i>正在加载讨论…</p><p v-else-if="!mrComments.length" class="git-repository-panel__comments-empty">尚无讨论，可留下审查意见。</p><article v-for="comment in mrComments" :key="comment.commentId"><span>{{ initials(comment.authorId) }}</span><div><b>{{ comment.authorId }}</b><time>{{ formatDate(comment.createdAt) }}</time><p>{{ comment.body }}</p></div></article><form @submit.prevent="createMergeComment"><textarea v-model.trim="mergeCommentBody" maxlength="4000" required placeholder="添加审查评论…"></textarea><button class="git-primary-button" :disabled="commentSubmitting">{{ commentSubmitting ? '发送中…' : '发送评论' }}</button></form></section></section>
      </section>
      <section v-else-if="activeTab === 'automation'" class="git-repository-panel__tab git-repository-panel__tab--card">
        <header class="git-repository-panel__section-head"><div><h2>自动化</h2><p>Git push 事件通过 <code>pcd.git.push.completed.v1</code> 触发已绑定的 CloudFlow 工作流。</p></div><button v-if="isOwner" type="button" class="git-primary-button" @click="showBindingForm = !showBindingForm"><i class="fa fa-plus"></i>绑定工作流</button></header>
        <form v-if="showBindingForm && isOwner" class="git-repository-panel__form" @submit.prevent="createWorkflowBinding"><select v-model="bindingForm.workflowId" required><option value="" disabled>选择已发布工作流</option><option v-for="workflow in workflows" :key="workflow.workflowId" :value="workflow.workflowId">{{ workflow.name }}</option></select><input v-model.trim="bindingForm.refPattern" required placeholder="refs/heads/main" /><button class="git-primary-button" :disabled="bindingSubmitting">{{ bindingSubmitting ? '绑定中…' : '确认绑定' }}</button></form>
        <div v-if="automationLoading" class="git-repository-panel__content-skeleton"><span v-for="index in 4" :key="index"></span></div><div v-else-if="!workflowBindings.length" class="git-empty"><i class="fa fa-random"></i><h2>暂无自动化绑定</h2><p>绑定已有工作流后，推送将作为事件事实触发 CloudFlow Runtime。</p></div><div v-else class="git-repository-panel__automation-list"><article v-for="binding in workflowBindings" :key="binding.bindingId"><span><i class="fa fa-random"></i></span><div><h3>{{ workflowName(binding.workflowId) }}</h3><p>{{ binding.refPattern }} · {{ binding.events.join('、') || 'git.push.completed' }}</p><small>{{ binding.enabled ? '已启用' : '已停用' }} · 运行历史由 CloudFlow Runtime 维护</small></div><router-link :to="`/app/workflows/${binding.workflowId}/edit`" class="git-secondary-button">查看运行</router-link></article></div>
      </section>
      <section v-else class="git-repository-panel__tab git-repository-panel__tab--card">
        <header class="git-repository-panel__section-head"><div><h2>贡献与语言</h2><p>来自当前 Git 提交和对象树的实时派生统计，不展示虚构的 Star/Fork 指标。</p></div></header>
        <div class="git-repository-panel__insights"><article><h3>语言分布</h3><div v-if="!insights.languages.length" class="git-empty git-empty--compact">尚无可统计的代码文件。</div><div v-else class="git-repository-panel__languages"><div v-for="language in insights.languages" :key="language.name"><span>{{ language.name }}</span><div><b :style="{ width: `${languagePercent(language.bytes)}%` }"></b></div><em>{{ formatFileSize(language.bytes) }}</em></div></div></article><article><h3>贡献者</h3><div v-if="!insights.contributors.length" class="git-empty git-empty--compact">尚无可统计的提交者。</div><div v-else class="git-repository-panel__contributors"><div v-for="contributor in insights.contributors" :key="`${contributor.name}-${contributor.email}`"><span>{{ initials(contributor.name) }}</span><p><b>{{ contributor.name }}</b><small>{{ contributor.email || '未提供邮箱' }}</small></p><em>{{ contributor.commits }} 提交</em></div></div></article><article class="git-repository-panel__contribution-card"><h3>贡献热力图</h3><div v-if="!heatmapCells.some((cell) => cell.count)" class="git-empty git-empty--compact">暂无近 12 个月提交记录。</div><div v-else class="git-repository-panel__heatmap" aria-label="近 12 个月提交热力图"><button v-for="cell in heatmapCells" :key="cell.date" type="button" :class="`level-${cell.level}`" :title="`${cell.date} · ${cell.count} 次提交`" @click="showToast(`${cell.date}：${cell.count} 次提交`, 'success')"></button></div><div class="git-repository-panel__heatmap-legend"><span>少</span><i class="level-0"></i><i class="level-1"></i><i class="level-2"></i><i class="level-3"></i><i class="level-4"></i><span>多</span></div></article></div>
      </section>
    </template>

    <!-- 原生 dialog 仅绑定 :open 时仍留在普通文档流，
         会在长仓库页的底部渲染。使用 Teleport 的模态层进入顶层并以 backdrop-filter
         聚焦克隆/管理任务，原有的分支、标签和凭证操作逻辑保持不变。 -->
    <Teleport to="body">
      <div v-if="cloneDialogOpen" class="git-repository-panel__modal" role="presentation" @click.self="cloneDialogOpen = false">
        <section class="git-repository-panel__dialog" role="dialog" aria-modal="true" aria-label="克隆仓库">
          <header><div><h2>克隆 {{ repository?.name }}</h2><p>使用 PAT 或 SSH 密钥与标准 Git CLI 通信。</p></div><button type="button" aria-label="关闭克隆窗口" @click="cloneDialogOpen = false"><i class="fa fa-times"></i></button></header>
          <label>HTTPS<input :value="repository?.httpCloneUrl" readonly @focus="selectInput" /></label><button type="button" class="git-secondary-button" @click="copy(repository?.httpCloneUrl, 'HTTPS 克隆地址已复制')"><i class="fa fa-copy"></i>复制 HTTPS 地址</button>
          <label>SSH<input :value="repository?.sshCloneUrl" readonly @focus="selectInput" /></label><button type="button" class="git-secondary-button" @click="copy(repository?.sshCloneUrl, 'SSH 克隆地址已复制')"><i class="fa fa-copy"></i>复制 SSH 地址</button><p class="git-repository-panel__dialog-tip"><code>git clone &lt;地址&gt;</code>；HTTPS 用户名可使用 <code>x-access-token</code>，密码填写个人访问令牌（PAT）。</p>
        </section>
      </div>
      <div v-if="isOwner && manageDialogOpen" class="git-repository-panel__modal" role="presentation" @click.self="manageDialogOpen = false">
        <section class="git-repository-panel__dialog git-repository-panel__dialog--wide" role="dialog" aria-modal="true" aria-label="分支与标签管理">
          <header><div><h2>分支与标签管理</h2><p>管理操作使用 Git Service Push 授权并保持默认分支保护边界。</p></div><button type="button" aria-label="关闭分支与标签管理" @click="manageDialogOpen = false"><i class="fa fa-times"></i></button></header>
          <div class="git-repository-panel__manage-grid"><section><h3>创建分支</h3><form @submit.prevent="createBranch"><input v-model.trim="branchForm.name" required maxlength="255" placeholder="feature/new-ui" /><select v-model="branchForm.startPoint"><option v-for="branch in branches" :key="branch.name" :value="branch.name">从 {{ branch.name }} 创建</option></select><button class="git-primary-button" :disabled="refSubmitting">创建分支</button></form><ul><li v-for="branch in branches" :key="branch.name"><span>{{ branch.name }}<b v-if="branch.name === repository?.defaultBranch">默认</b></span><button type="button" :disabled="branch.name === repository?.defaultBranch || refSubmitting" @click="removeBranch(branch.name)"><i class="fa fa-trash"></i></button></li></ul></section><section><h3>创建标签</h3><form @submit.prevent="createTag"><input v-model.trim="tagForm.name" required maxlength="255" placeholder="v1.0.0" /><select v-model="tagForm.target"><option v-for="branch in branches" :key="branch.name" :value="branch.name">指向 {{ branch.name }}</option></select><input v-model.trim="tagForm.message" maxlength="500" placeholder="附注（可选）" /><button class="git-primary-button" :disabled="refSubmitting">创建标签</button></form><ul><li v-for="tag in tags" :key="tag.name"><span>{{ tag.name }}</span><button type="button" :disabled="refSubmitting" @click="removeTag(tag.name)"><i class="fa fa-trash"></i></button></li></ul></section></div>
        </section>
      </div>
      <div v-if="forkDialogOpen" class="git-repository-panel__modal" role="presentation" @click.self="forkDialogOpen = false">
        <section class="git-repository-panel__dialog" role="dialog" aria-modal="true" aria-label="Fork 仓库">
          <header><div><h2>Fork {{ repository?.name }}</h2><p>Fork 是公开空间 Git 资源的独立副本，默认私有。</p></div><button type="button" aria-label="关闭 Fork 窗口" @click="forkDialogOpen = false"><i class="fa fa-times"></i></button></header>
          <label>目标 Git 空间<select v-model="forkForm.targetSpaceId"><option value="" disabled>选择目标空间</option><option v-for="space in forkSpaces" :key="space.spaceId" :value="space.spaceId">{{ space.spaceName }}</option></select></label>
          <label>新仓库名称<input v-model.trim="forkForm.name" maxlength="128" placeholder="仓库名称" /></label>
          <label>仓库可见性<select v-model="forkForm.visibility"><option value="PRIVATE">私密</option><option value="HIDDEN">隐藏</option><option value="PUBLIC">公开</option></select></label>
          <button type="button" class="git-primary-button git-repository-panel__dialog-submit" :disabled="forkSubmitting || !forkForm.targetSpaceId" @click="submitFork">{{ forkSubmitting ? 'Fork 中…' : '确认 Fork' }}</button>
        </section>
      </div>
    </Teleport>
  </section>
</template>

<script setup lang="ts">
// [REQ-GIT-UIUX-20260816] Git 类型空间从原“平铺目录 + 原始文本 + 线性提交列表”改为
// GitHub 式仓库工作区：代码树/预览、提交 DAG、MR、自动化和真实洞察分离加载。
// 普通 file 资源空间仍由 PublicSpaceView 的原文件浏览流程渲染，影响范围仅 resource_type=git。
import { computed, onBeforeUnmount, onMounted, provide, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import GitCodeWorkspace from '@/components/git/GitCodeWorkspace.vue'
import GitCommitGraph from '@/components/git/GitCommitGraph.vue'
import GitDiffViewer from '@/components/git/GitDiffViewer.vue'
import MarkdownPreview from '@/components/preview/MarkdownPreview.vue'
import { useToastStore } from '@/stores/toastStore'
import { ApiError } from '@/utils/request'
import { formatFileSize } from '@/utils/helpers'
import { formatGitRelativeTime } from '@/utils/gitRepositoryPresentation'
import { listSpacesApi, type SpaceInfo } from '@/api/modules/space'
import { listWorkflowsApi, type WorkflowInfo } from '@/api/modules/workflows'
import {
  createGitBranchApi, createGitMergeRequestApi, createGitMergeRequestCommentApi, createGitRepositoryApi, createGitTagApi, createGitWorkflowBindingApi,
  deleteGitBranchApi, deleteGitTagApi, getGitArchiveApi, getGitDiffApi, getGitReadmeApi, getGitRepositoryBySpaceApi,
  forkGitRepositoryApi, getGitRepositoryInsightsApi, getGitRepositorySocialStatsApi, listGitBranchesApi, listGitMergeRequestCommentsApi, listGitMergeRequestsApi, listGitTagsApi, listGitWorkflowBindingsApi, mergeGitMergeRequestApi, reviewGitMergeRequestApi, starGitRepositoryApi, unstarGitRepositoryApi,
  type GitMergeRequest, type GitMergeRequestComment, type GitRef, type GitRepository, type GitRepositoryInsights, type GitWorkflowBinding,
} from '@/api/modules/git'

type TabId = 'code' | 'readme' | 'commits' | 'merge-requests' | 'automation' | 'insights'
const props = defineProps<{ spaceId: string; spaceName: string; description?: string | null; isOwner: boolean }>()
const route = useRoute(); const router = useRouter(); const toast = useToastStore()
const repository = ref<GitRepository | null>(null)
const branches = ref<GitRef[]>([]); const tags = ref<GitRef[]>([])
const insights = ref<GitRepositoryInsights>({ commitCount: 0, contributorCount: 0, branchCount: 0, tagCount: 0, languages: [], contributors: [], contributions: [] })
const selectedRef = ref('main'); const activeTab = ref<TabId>(tabFromRoute())
const loading = ref(true); const error = ref(''); const isDark = ref(document.documentElement.classList.contains('dark'))
// [REQ-GIT-ICON-20260818 / 3.16] 页面级配置：仓库页内所有 FileTypeIcon 默认使用单色，其他页面不受影响。
provide('gitIconColorMode', 'monochrome')
const readmeName = ref(''); const readmeContent = ref(''); const readmeLoading = ref(false)
const mergeRequests = ref<GitMergeRequest[]>([]); const mergeLoading = ref(false); const mergeSubmitting = ref(false); const mrStatus = ref(''); const selectedMergeRequest = ref<GitMergeRequest | null>(null); const mrDiff = ref(''); const mrDiffLoading = ref(false); const showMergeForm = ref(false); const mrComments = ref<GitMergeRequestComment[]>([]); const commentsLoading = ref(false); const mergeCommentBody = ref(''); const commentSubmitting = ref(false)
const workflows = ref<WorkflowInfo[]>([]); const workflowBindings = ref<GitWorkflowBinding[]>([]); const automationLoading = ref(false); const bindingSubmitting = ref(false); const showBindingForm = ref(false)
const cloneDialogOpen = ref(false); const manageDialogOpen = ref(false); const forkDialogOpen = ref(false); const refSubmitting = ref(false); const socialBusy = ref(false); const forkSubmitting = ref(false); const historyPath = ref('')
const forkSpaces = ref<SpaceInfo[]>([])
const forkForm = reactive({ targetSpaceId: '', name: '', visibility: 'PRIVATE' as 'PRIVATE' | 'HIDDEN' | 'PUBLIC' })
const mergeForm = reactive({ title: '', description: '', sourceBranch: '', targetBranch: '' }); const bindingForm = reactive({ workflowId: '', refPattern: 'refs/heads/main' }); const branchForm = reactive({ name: '', startPoint: 'main' }); const tagForm = reactive({ name: '', target: 'main', message: '' })
let themeObserver: MutationObserver | null = null

const routePath = computed(() => typeof route.query.path === 'string' ? route.query.path : '')
const routeLine = computed(() => { const value = Number(route.query.line); return Number.isInteger(value) && value > 0 ? value : null })
const allRefs = computed(() => [...branches.value, ...tags.value])
const heatmapCells = computed(() => {
  const counts = new Map((insights.value.contributions || []).map((item) => [item.date, item.count]))
  const today = new Date(); const start = new Date(today); start.setDate(today.getDate() - 364)
  return Array.from({ length: 365 }, (_, index) => { const date = new Date(start); date.setDate(start.getDate() + index); const key = date.toISOString().slice(0, 10); const count = counts.get(key) || 0; return { date: key, count, level: count === 0 ? 0 : count < 2 ? 1 : count < 5 ? 2 : count < 10 ? 3 : 4 } })
})
const tabs = computed(() => [
  { id: 'code' as TabId, label: '代码', icon: 'fa fa-code' }, { id: 'readme' as TabId, label: 'README', icon: 'fa fa-book' },
  { id: 'commits' as TabId, label: '提交图', icon: 'fa fa-code-fork', count: insights.value.commitCount }, { id: 'merge-requests' as TabId, label: '合并请求', icon: 'fa fa-random', count: mergeRequests.value.length },
  { id: 'automation' as TabId, label: '自动化', icon: 'fa fa-bolt', count: workflowBindings.value.length }, { id: 'insights' as TabId, label: '洞察', icon: 'fa fa-bar-chart' },
])

onMounted(() => { themeObserver = new MutationObserver(() => { isDark.value = document.documentElement.classList.contains('dark') }); themeObserver.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] }); void loadAll(); window.addEventListener('keydown', onKeyboardShortcut) })
onBeforeUnmount(() => { themeObserver?.disconnect(); window.removeEventListener('keydown', onKeyboardShortcut) })
watch(() => route.query.tab, () => { activeTab.value = tabFromRoute() })
watch([() => repository.value?.name, () => activeTab.value], () => { if (repository.value) document.title = `${repository.value.name} - ${tabTitle(activeTab.value)} - 私有云盘` })

function tabFromRoute(): TabId { const candidate = route.query.tab; return typeof candidate === 'string' && ['code', 'readme', 'commits', 'merge-requests', 'automation', 'insights'].includes(candidate) ? candidate as TabId : 'code' }
function tabTitle(tab: TabId): string { return ({ code: '代码', readme: 'README', commits: '提交图', 'merge-requests': '合并请求', automation: '自动化', insights: '洞察' })[tab] }
async function loadAll(): Promise<void> {
  loading.value = true; error.value = ''
  try {
    let response
    try { response = await getGitRepositoryBySpaceApi(props.spaceId) } catch (cause) {
      // [REQ-GIT-SPACE-12.2] 公开空间创建和仓库初始化分开，所有者首次访问时补建 Git 仓库。
      if (!props.isOwner || !(cause instanceof ApiError) || cause.status !== 404) throw cause
      response = await createGitRepositoryApi({ spaceId: props.spaceId, name: props.spaceName, description: props.description || '' })
    }
    repository.value = response.data
    // [REQ-GIT-UIUX-20260816] 原行为每次初始化都回到默认分支；新行为优先恢复 URL 中的
    // ref，使浏览器前进/后退和分享链接保持仓库上下文。loadRefs 会回退不存在的引用。
    selectedRef.value = typeof route.query.ref === 'string' && route.query.ref ? route.query.ref : repository.value.defaultBranch
    branchForm.startPoint = selectedRef.value; tagForm.target = selectedRef.value; bindingForm.refPattern = `refs/heads/${selectedRef.value}`
    await Promise.all([loadRefs(), loadInsights(), loadMergeRequests(), loadSocialStats()]); await ensureActiveTabLoaded()
  } catch (cause: any) { error.value = cause?.message || 'Git 仓库加载失败，请稍后重试' } finally { loading.value = false }
}
async function loadRefs(): Promise<void> { if (!repository.value) return; const [branchResult, tagResult] = await Promise.allSettled([listGitBranchesApi(repository.value.repoId), listGitTagsApi(repository.value.repoId)]); branches.value = branchResult.status === 'fulfilled' ? branchResult.value.data || [] : []; tags.value = tagResult.status === 'fulfilled' ? tagResult.value.data || [] : []; if (!allRefs.value.some((item) => item.name === selectedRef.value)) selectedRef.value = repository.value.defaultBranch }
async function loadInsights(): Promise<void> { if (!repository.value) return; try { insights.value = (await getGitRepositoryInsightsApi(repository.value.repoId)).data || insights.value } catch { /* 洞察失败不阻断代码浏览；保留真实零值而不虚构指标。 */ } }
async function loadSocialStats(): Promise<void> { if (!repository.value) return; try { const result = (await getGitRepositorySocialStatsApi(repository.value.repoId)).data; repository.value = { ...repository.value, ...result } } catch { /* Star/Fork 统计失败不阻断仓库浏览。 */ } }
async function toggleStar(): Promise<void> { if (!repository.value || socialBusy.value) return; socialBusy.value = true; try { const result = (await (repository.value.starred ? unstarGitRepositoryApi(repository.value.repoId) : starGitRepositoryApi(repository.value.repoId))).data; repository.value = { ...repository.value, ...result }; showToast(repository.value.starred ? '已 Star 仓库' : '已取消 Star', 'success') } catch (cause: any) { showToast(cause?.message || 'Star 操作失败', 'error') } finally { socialBusy.value = false } }
async function openForkDialog(): Promise<void> { if (!repository.value) return; forkForm.name = repository.value.name; forkForm.targetSpaceId = ''; forkForm.visibility = 'PRIVATE'; forkDialogOpen.value = true; try { forkSpaces.value = ((await listSpacesApi()).data || []).filter((space) => space.resourceType === 'git' && space.spaceStatus === 'active') } catch (cause: any) { showToast(cause?.message || '目标空间加载失败', 'error') } }
async function submitFork(): Promise<void> { if (!repository.value || !forkForm.targetSpaceId || forkSubmitting.value) return; forkSubmitting.value = true; try { const result = (await forkGitRepositoryApi(repository.value.repoId, { ...forkForm })).data; forkDialogOpen.value = false; showToast(`Fork 成功：${result.name}`, 'success'); if (result.spaceId) window.open(`/repo/${result.spaceId}`, '_blank') } catch (cause: any) { showToast(cause?.message || 'Fork 失败', 'error') } finally { forkSubmitting.value = false } }
async function changeRef(refName: string): Promise<void> { selectedRef.value = refName; readmeContent.value = ''; historyPath.value = ''; syncRoute({ ref: refName, path: undefined, line: undefined }); await ensureActiveTabLoaded() }
async function ensureActiveTabLoaded(): Promise<void> { if (activeTab.value === 'readme') await loadReadme(); if (activeTab.value === 'automation') await loadAutomation(); if (activeTab.value === 'merge-requests') await loadMergeRequests() }
async function setTab(tab: TabId): Promise<void> { activeTab.value = tab; syncRoute({ tab }); await ensureActiveTabLoaded() }
async function loadReadme(): Promise<void> { if (!repository.value || readmeLoading.value) return; readmeLoading.value = true; try { const data = (await getGitReadmeApi(repository.value.repoId, selectedRef.value)).data; readmeName.value = data?.name || ''; readmeContent.value = data?.content || '' } catch (cause: any) { error.value = cause?.message || 'README 读取失败' } finally { readmeLoading.value = false } }
async function loadMergeRequests(): Promise<void> { if (!repository.value || mergeLoading.value) return; mergeLoading.value = true; try { mergeRequests.value = (await listGitMergeRequestsApi(repository.value.repoId, mrStatus.value)).data || [] } catch (cause: any) { error.value = cause?.message || '合并请求加载失败' } finally { mergeLoading.value = false } }
async function createMergeRequest(): Promise<void> { if (!repository.value || mergeSubmitting.value) return; mergeSubmitting.value = true; try { await createGitMergeRequestApi(repository.value.repoId, { ...mergeForm }); Object.assign(mergeForm, { title: '', description: '', sourceBranch: '', targetBranch: '' }); showMergeForm.value = false; await loadMergeRequests(); showToast('合并请求已创建', 'success') } catch (cause: any) { showToast(cause?.message || '合并请求创建失败', 'error') } finally { mergeSubmitting.value = false } }
async function selectMergeRequest(item: GitMergeRequest): Promise<void> { selectedMergeRequest.value = item; mrDiff.value = ''; mrComments.value = []; commentsLoading.value = true; try { mrComments.value = (await listGitMergeRequestCommentsApi(repository.value!.repoId, item.mergeRequestId)).data || [] } catch (cause: any) { showToast(cause?.message || '合并请求讨论加载失败', 'error') } finally { commentsLoading.value = false } }
async function loadMergeDiff(): Promise<void> { if (!repository.value || !selectedMergeRequest.value) return; mrDiffLoading.value = true; try { mrDiff.value = (await getGitDiffApi(repository.value.repoId, selectedMergeRequest.value.targetBranch, selectedMergeRequest.value.sourceBranch)).data.diff || '没有可显示的文本差异' } catch (cause: any) { showToast(cause?.message || '合并请求差异读取失败', 'error') } finally { mrDiffLoading.value = false } }
async function createMergeComment(): Promise<void> { if (!repository.value || !selectedMergeRequest.value || !mergeCommentBody.value.trim() || commentSubmitting.value) return; commentSubmitting.value = true; try { await createGitMergeRequestCommentApi(repository.value.repoId, selectedMergeRequest.value.mergeRequestId, mergeCommentBody.value.trim()); mergeCommentBody.value = ''; await selectMergeRequest(selectedMergeRequest.value); showToast('审查评论已发送', 'success') } catch (cause: any) { showToast(cause?.message || '评论发送失败', 'error') } finally { commentSubmitting.value = false } }
async function reviewMergeRequest(decision: 'APPROVED' | 'CHANGES_REQUESTED'): Promise<void> { if (!repository.value || !selectedMergeRequest.value) return; const mergeRequestId = selectedMergeRequest.value.mergeRequestId; try { await reviewGitMergeRequestApi(repository.value.repoId, mergeRequestId, decision); await loadMergeRequests(); selectedMergeRequest.value = mergeRequests.value.find((item) => item.mergeRequestId === mergeRequestId) || null; showToast(decision === 'APPROVED' ? '已批准该合并请求' : '已请求修改', 'success') } catch (cause: any) { showToast(cause?.message || '审批操作失败', 'error') } }
async function mergeMergeRequest(): Promise<void> { if (!repository.value || !selectedMergeRequest.value || !window.confirm('确认合并该合并请求吗？')) return; const mergeRequestId = selectedMergeRequest.value.mergeRequestId; try { await mergeGitMergeRequestApi(repository.value.repoId, mergeRequestId); await Promise.all([loadMergeRequests(), loadRefs(), loadInsights()]); selectedMergeRequest.value = mergeRequests.value.find((item) => item.mergeRequestId === mergeRequestId) || null; showToast('合并请求已合并', 'success') } catch (cause: any) { showToast(cause?.message || '合并失败', 'error') } }
async function loadAutomation(): Promise<void> { if (!repository.value || automationLoading.value) return; automationLoading.value = true; try { const requests: Promise<any>[] = [listGitWorkflowBindingsApi(repository.value.repoId)]; if (props.isOwner) requests.push(listWorkflowsApi(1, 100)); const [bindingResponse, workflowResponse] = await Promise.all(requests); workflowBindings.value = bindingResponse.data || []; workflows.value = workflowResponse ? (workflowResponse.data || []).filter((item: WorkflowInfo) => item.status === 'PUBLISHED') : [] } catch (cause: any) { error.value = cause?.message || '自动化配置加载失败' } finally { automationLoading.value = false } }
async function createWorkflowBinding(): Promise<void> { if (!repository.value || !bindingForm.workflowId || bindingSubmitting.value) return; bindingSubmitting.value = true; try { await createGitWorkflowBindingApi(repository.value.repoId, { workflowId: bindingForm.workflowId, refPattern: bindingForm.refPattern, events: ['pcd.git.push.completed.v1'] }); showBindingForm.value = false; await loadAutomation(); showToast('自动化工作流已绑定', 'success') } catch (cause: any) { showToast(cause?.message || '自动化绑定失败', 'error') } finally { bindingSubmitting.value = false } }
function workflowName(workflowId: string): string { return workflows.value.find((item) => item.workflowId === workflowId)?.name || workflowId }
async function createBranch(): Promise<void> { if (!repository.value || refSubmitting.value) return; refSubmitting.value = true; try { await createGitBranchApi(repository.value.repoId, { ...branchForm }); branchForm.name = ''; await loadRefs(); await loadInsights(); showToast('分支已创建', 'success') } catch (cause: any) { showToast(cause?.message || '分支创建失败', 'error') } finally { refSubmitting.value = false } }
async function createTag(): Promise<void> { if (!repository.value || refSubmitting.value) return; refSubmitting.value = true; try { await createGitTagApi(repository.value.repoId, { ...tagForm }); Object.assign(tagForm, { name: '', target: selectedRef.value, message: '' }); await loadRefs(); await loadInsights(); showToast('标签已创建', 'success') } catch (cause: any) { showToast(cause?.message || '标签创建失败', 'error') } finally { refSubmitting.value = false } }
async function removeBranch(name: string): Promise<void> { if (!repository.value || !window.confirm(`确定删除分支 ${name} 吗？`)) return; refSubmitting.value = true; try { await deleteGitBranchApi(repository.value.repoId, name); await loadRefs(); await loadInsights(); showToast('分支已删除', 'success') } catch (cause: any) { showToast(cause?.message || '分支删除失败', 'error') } finally { refSubmitting.value = false } }
async function removeTag(name: string): Promise<void> { if (!repository.value || !window.confirm(`确定删除标签 ${name} 吗？`)) return; refSubmitting.value = true; try { await deleteGitTagApi(repository.value.repoId, name); await loadRefs(); await loadInsights(); showToast('标签已删除', 'success') } catch (cause: any) { showToast(cause?.message || '标签删除失败', 'error') } finally { refSubmitting.value = false } }
async function downloadArchive(): Promise<void> { if (!repository.value) return; try { const archive = await getGitArchiveApi(repository.value.repoId, selectedRef.value); const url = URL.createObjectURL(archive); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `${repository.value.slug}-${selectedRef.value.replace(/\//g, '-')}.zip`; anchor.click(); URL.revokeObjectURL(url); showToast('仓库 ZIP 下载已开始', 'success') } catch (cause: any) { showToast(cause?.message || '仓库归档下载失败', 'error') } }
function openFileHistory(path: string): void { historyPath.value = path; void setTab('commits') }
function syncFilePath(path: string): void { syncRoute({ path: path || undefined, line: undefined }) }
function syncRoute(values: Record<string, string | undefined>): void { const query = { ...route.query, ...values }; Object.keys(query).forEach((key) => { if (query[key] === undefined || query[key] === '') delete query[key] }); void router.replace({ query }) }
function onKeyboardShortcut(event: KeyboardEvent): void { if ((event.target as HTMLElement | null)?.matches('input,textarea,select,[contenteditable="true"]')) return; if (event.key.toLowerCase() === 't') { event.preventDefault(); void setTab('code'); window.setTimeout(() => document.querySelector<HTMLInputElement>('.git-file-tree__search input')?.focus(), 0) } if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'f') { event.preventDefault(); if (activeTab.value === 'code') window.setTimeout(() => document.querySelector<HTMLInputElement>('.git-file-tree__search input')?.focus(), 0) } }
async function copy(value: string | undefined, message: string): Promise<void> { if (!value) return; try { await navigator.clipboard.writeText(value); showToast(message, 'success') } catch { showToast('当前浏览器不允许自动复制', 'warning') } }
function selectInput(event: Event): void { (event.target as HTMLInputElement).select() }
function formatDate(value?: string): string { return value ? new Date(value).toLocaleString('zh-CN') : '—' }; function formatRelative(value?: string): string { return formatGitRelativeTime(value) }; function initials(name: string): string { return name.split(/\s+/).map((item) => item[0]).join('').slice(0, 2).toUpperCase() || '?' }; function languagePercent(bytes: number): number { const total = insights.value.languages.reduce((sum, item) => sum + item.bytes, 0); return total ? Math.max(3, Math.round(bytes / total * 100)) : 0 }; function showToast(message: string, type: 'success' | 'error' | 'warning' = 'success'): void { toast.showToast(message, type) }
</script>

